"""Compile the peaceful score with the SDK's A2 encoder into a C++20 asset."""

import argparse
import runpy
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def generate(compiler):
    encoder = runpy.run_path(str(compiler))
    source = ROOT / "assets/music/peaceful.avms"
    data = encoder["compile_source"](source.read_text(encoding="utf-8"), source)
    header = encoder["c_array"](data, "PEACEFUL_MUSIC")
    return header.replace(
        "/* Generated by avm_music.py. */",
        "/* Generated by tools/generate_music.py; do not edit. */",
    ).replace(
        "static const uint64_t", "constexpr uint64_t"
    ).replace(
        "static const AVM_PROGMEM struct", "constexpr AVM_PROGMEM struct"
    )


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--compiler", type=Path, required=True)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    header = generate(args.compiler)
    output = ROOT / "generated/peaceful_music.h"
    if args.check:
        if not output.exists() or output.read_text(encoding="utf-8") != header:
            raise SystemExit(
                "peaceful_music.h is stale; run tools/generate_music.py --compiler <avm_music.py>"
            )
    else:
        output.write_text(header, encoding="utf-8", newline="\n")


if __name__ == "__main__":
    main()
